const root=process.cwd(),apply=process.argv.includes('--apply');
const sha=b=>crypto.createHash('sha256').update(b.toString('utf8').replace(/\r\n/g,'\n')).digest('hex');
function run(){
 for(const n of ['home-services.html','shop.html','seller-dashboard-test/connected.html'])if(!fs.existsSync(path.join(root,n)))throw Error('Run this inside catus-frontend. Missing: '+n);
 const writes=[],removes=[];
 for(const item of PLAN.writes){const file=path.join(root,item.path),next=Buffer.from(item.data,'base64'),existing=fs.existsSync(file)?fs.readFileSync(file):null;if(existing&&sha(existing)===sha(next))continue;if((existing?sha(existing):null)!==item.before)throw Error('File changed since audit; stopped without changes: '+item.path);writes.push({...item,next,existing});}
 for(const item of PLAN.remove){const file=path.join(root,item.path);if(!fs.existsSync(file))continue;const existing=fs.readFileSync(file);if(sha(existing)!==item.before)throw Error('Old file changed since audit; stopped without changes: '+item.path);removes.push({...item,existing});}
 const removed=new Set(PLAN.remove.filter(x=>x.path.endsWith('.html')||x.path.endsWith('.js')||x.path.endsWith('.css')).map(x=>x.path));
 const planned=new Map(PLAN.writes.map(x=>[x.path,Buffer.from(x.data,'base64').toString()]));
 function scan(dir){for(const ent of fs.readdirSync(dir,{withFileTypes:true})){if(['.git','node_modules','.netlify','.vercel'].includes(ent.name))continue;const full=path.join(dir,ent.name),rel=path.relative(root,full).split(path.sep).join('/');if(ent.isSymbolicLink())continue;if(ent.isDirectory()){scan(full);continue;}if(removed.has(rel)||rel==='apply-frontend-cleanup.cjs'||rel==='vercel.json'||! /\.(html|js|css|json)$/.test(rel))continue;const text=planned.get(rel)??fs.readFileSync(full,'utf8');for(const name of removed)if(text.includes(name))throw Error('Unresolved reference to '+name+' in '+rel+'; stopped without changes.');}}
 scan(root);
 console.log('Update/add '+writes.length+' files; remove '+removes.length+' retired files.');
 if(!writes.length&&!removes.length){console.log('Cleanup already applied.');return;}
 if(!apply){console.log('CHECK PASSED. No files changed. Run: node apply-frontend-cleanup.cjs --apply');return;}
 const backup=path.join(path.dirname(root),'cerood-frontend-backups',path.basename(root)+'-cleanup-'+Date.now());
 fs.mkdirSync(backup,{recursive:true});
 const items=[...writes,...removes];
 for(const x of items)if(x.existing){const target=path.join(backup,x.path);fs.mkdirSync(path.dirname(target),{recursive:true});fs.writeFileSync(target,x.existing);}
 fs.writeFileSync(path.join(backup,'cleanup-manifest.json'),JSON.stringify({writes:writes.map(x=>({path:x.path,wasNew:!x.existing})),removed:removes.map(x=>x.path)},null,2));
 try{for(const x of writes){const file=path.join(root,x.path);fs.mkdirSync(path.dirname(file),{recursive:true});fs.writeFileSync(file,x.next);}for(const x of removes)fs.unlinkSync(path.join(root,x.path));}
 catch(error){for(const x of items){const file=path.join(root,x.path);if(x.existing)fs.writeFileSync(file,x.existing);else if(fs.existsSync(file))fs.unlinkSync(file);}throw error;}
 console.log('Cleanup complete. Backup: '+backup);console.log('No backend/database changes. Review git diff before committing.');
}
